const query = $input.first().json.query || {};

// Pagination
const page = Math.max(1, parseInt(query.page) || 1);
const limit = Math.min(parseInt(query.limit) || 10, 100);
const offset = (page - 1) * limit;

// Sorting
const sortBy = ['first_name', 'last_name', 'commission', 'last_summary', 'created_at'].includes(query.sort_by) 
  ? query.sort_by 
  : 'created_at';
const sortOrder = query.sort_order === 'asc' ? 'ASC' : 'DESC';

// Filters
const search = query.search || null;
const isAdmin = query.is_admin === 'true' ? true : query.is_admin === 'false' ? false : null;
const isDeleted = query.is_deleted === 'true' ? true : query.is_deleted === 'false' ? false : null;
const role = query.role || null;
const branch = query.branch || null;

// Commission range
const commissionMin = query.commission_min ? parseFloat(query.commission_min) : null;
const commissionMax = query.commission_max ? parseFloat(query.commission_max) : null;

// Date ranges
const from = query.from || null;
const to = query.to || null;
const lastSummaryFrom = query.last_summary_from || null;
const lastSummaryTo = query.last_summary_to || null;

return [{
  json: {
    page, limit, offset, sortBy, sortOrder,
    search, isAdmin, isDeleted, role, branch,
    commissionMin, commissionMax,
    from, to, lastSummaryFrom, lastSummaryTo
  }
}];

