const users = $('Fetch Users').all().map(item => item.json);
const total = $('Count Users').all()[0]?.json?.total || 0;
const page = $('Parse Parameters').first().json.page;
const limit = $('Parse Parameters').first().json.limit;

// Format the data
const formattedUsers = users.map(user => ({
  ...user,
  full_name: `${user.first_name || ''} ${user.last_name || ''}`.trim(),
  commission_formatted: `${user.commission || 0}%`,
  status: user.is_deleted ? 'Deleted' : 'Active',
  admin_status: user.is_admin ? 'Yes' : 'No'
}));

return [{
  json: {
    data: formattedUsers,
    recordsTotal: total,
    recordsFiltered: total,
    page: page,
    limit: limit,
    totalPages: Math.ceil(total / limit)
  }
}];
